module parity_8bit (
    input [7:0] in,
    output out
);
    wire [7:0] and_out1, xor1_out1, xor2_out1, xor3_out1, xor4_out1, xor5_out1, xor6_out1, xor7_out1, xor8_out1;
    assign and_out1 = {8{1'b1}} & in;
    assign xor1_out1 = and_out1 ^ in [0];
    assign xor2_out1 = and_out1 ^ in [1];
    assign xor3_out1 = and_out1 ^ in [2];
    assign xor4_out1 = and_out1 ^ in [3];
    assign xor5_out1 = and_out1 ^ in [4];
    assign xor6_out1 = and_out1 ^ in [5];
    assign xor7_out1 = and_out1 ^ in [6];
    assign xor8_out1 = and_out1 ^ in [7];
    wire z1, z2;
    assign z1 = xor1_out1 ^ xor2_out1 ^ xor3_out1 ^ xor4_out1;
    assign z2 = xor5_out1 ^ xor6_out1 ^ xor7_out1 ^ xor8_out1;
    assign out = z1 ^ z2;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    assign out = (sel == 2'b00) ? in[3] : 
                 (sel == 2'b01) ? in[2] : 
                 (sel == 2'b10) ? in[1] : 
                 (sel == 2'b11) ? in[0] : 1'b0;
endmodule

module majority (
    input a, b, c,
    output out
);
    wire w1, w2, w3, w4;
    assign w1 = a & b;
    assign w2 = b & c;
    assign w3 = c & a;
    assign w4 = w1 | w2 | w3;
    assign out = w4;
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[0] = binary[0];
    assign gray[1] = binary[0] ^ binary[1];
    assign gray[2] = binary[1] ^ binary[2];
    assign gray[3] = binary[2] ^ binary[3];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] and1, and2, and3, and4;
    wire [3:0] or1, or2, or3, or4;
    wire [3:0] and5, and6, and7, and8;
    wire [3:0] or5, or6, or7, or8;

    // 1st level (A0 & B0, A1 & B1, A2 & B2, A3 & B3) -> first and gates
    assign and1[0] = a[0] & b[0];
    assign and1[1] = a[1] & b[1];
    assign and1[2] = a[2] & b[2];
    assign and1[3] = a[3] & b[3];

    // 2nd level (A0 | B0, A1 | B1, A2 | B2, A3 | B3) -> first or gates
    assign or1[0] = a[0] | b[0];
    assign or1[1] = a[1] | b[1];
    assign or1[2] = a[2] | b[2];
    assign or1[3] = a[3] | b[3];

    // 3rd level (A0 & B0 & A1 & B1 & A2 & B2 & A3 & B3) -> and combination
    assign and2[0] = and1[0] & and1[1] & and1[2] & and1[3];
    assign and2[1] = or1[0] & or1[1] & or1[2] & or1[3];
    assign and2[2] = and1[0] & and1[1] & and1[2] & or1[3];
    assign and2[3] = or1[0] & and1[1] & and1[2] & and1[3];

    // 4th level (A0, A1, A2, A3) -> or gates
    assign or2[0] = a[0] | a[1] | a[2] | a[3];
    assign or2[1] = a[0] | a[1] | a[2] | b[3];
    assign or2[2] = a[0] | a[1] | b[2] | b[3];
    assign or2[3] = a[0] | b[1] | b[2] | b[3];

    // 5th level (A & B comparison) -> final and gates
    assign and3[0] = and2[0] & or2[0];
    assign and3[1] = and2[1] & or2[1];
    assign and3[2] = and2[2] & or2[2];
    assign and3[3] = and2[3] & or2[3];

    // 6th level (logical combination) -> final or gates
    assign or3[0] = and3[0] | and3[1] | and3[2] | and3[3];

    assign equal = or3[0];
endmodule

