module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    wire [7:0] partial_products;
    assign partial_products = {b, {4'b0, a[0]}} & a; // Multiply a[0] by b
    assign partial_products[7:4] = {b, {4'b0, a[1]}} & a; // Multiply a[1] by b
    assign partial_products[3:0] = {b, {4'b0, a[2]}} & a; // Multiply a[2] by b
    assign out = partial_products; // Cộng toàn bộ kết quả
endmodule

