module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    wire [7:0] rotated_in;
    assign rotated_in = {in[6:0], in[7]};
    wire [7:0] shifted_in;
    assign shifted_in = {shifted_in[6:0], in[7]};
    wire [7:0] final_out;
    assign final_out = rotated_in >> {2, 1, 0};
    assign out = final_out;
endmodule

