module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] mux_select = {data_in[7], data_in[6], data_in[5], data_in[4], data_in[3], data_in[2], data_in[1], data_in[0]};
    wire [7:0] select = {4'b0000, 4'b0001, 4'b0010, 4'b0011, 4'b0100, 4'b0101, 4'b0110, 4'b0111};
    wire [7:0] mux_out;
    assign mux_out = select & mux_select;
    wire [7:0] output_mux = {mux_out, select};
    assign data_out = output_mux;
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg [1:0] state;
    always @(posedge clk orposedge rst) begin
        if (rst) 
            state <= 2'b00;
        else 
            state <= state + 1'b1;
    end
    assign clk_out = ~(state == 2'b01);
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] a0, b0, a_diff, b_diff, out_diff;
    assign a0 = a; assign b0 = b;
    wire [3:0] c;
    assign c = a - b;
    wire [2:0] count;
    always @(a or b) begin
        for (int i = 0; i < 4; i++) begin
            count[i] = (b0[i] == a0[i]) ? 1 : 0;
        end
    end
    wire [3:0] count0;
    assign count0 = count;
    wire z = (a0 == b0);
    assign eq = z;
    assign lt = (c < 0) ? 1 : 0;
    assign gt = (c > 0) ? 1 : 0;
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);
    wire a0 = in[1] & in[0] & enable;
    wire a1 = in[1] & ~in[0] & enable;
    wire a2 = ~in[1]  & in[0] & enable;
    wire a3 = ~in[1]  & ~in[0] & enable;
    assign out = {a3, a2, a1, a0};
endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
  wire a, b, c, d, e, f, g, h;
  assign a = enable && (~in[2]) && (~in[1]) && (~in[0]);
  assign b = enable && (~in[2]) && (~in[1]) && in[0];
  assign c = enable && (~in[2]) && in[1] && (~in[0]);
  assign d = enable && (~in[2]) && in[1] && in[0];
  assign e = enable && in[2] && (~in[1]) && (~in[0]);
  assign f = enable && in[2] && (~in[1]) && in[0];
  assign g = enable && in[2] && in[1] && (~in[0]);
  assign h = enable && in[2] && in[1] && in[0];
  assign out = {h, g, f, e, d, c, b, a};
endmodule

