    input rst,
    output [3:0] q
);
    reg [3:0] q_register;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q_register <= 4'b1111;
        end else begin
            q_register <= {q_register[3], q_register[2], q_register[1], ~q_register[0]};
        end
    end
    assign q = q_register;
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    reg [7:0] shift_reg;
    reg [7:0] d_reg;

    always @(posedge clk) begin
        if (rst) begin
            d_reg <= 0;
            shift_reg <= 0;
        end
        else if (load) begin
            d_reg <= pin;
        end
        else begin
            shift_reg <= {shift_reg[6:0], d_reg[0]};
            d_reg <= {d_reg[6:0], shift_reg[0]};
        end
    end

    assign sout = shift_reg[7];
endmodule

module priority_encoder_4to2 (
    input [3:0] in,
    output [1:0] out,
    output valid
);
