module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
	parameter D_width = 8;
	reg [D_width-1:0] D;
	logic [D_width-1:0] Q;
	reg [D_width-1:0] count;
	always @(posedge clk) begin
		if (rst) begin
			Q <= 0;
			count <= 0;
		end
		else begin
			Q <= Q + 1;
			count <= Q;
		end
	end
endmodule

module TopModule (
