module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);
  wire b1 = (sel_b1) ? b : 1'b0;
  wire b2 = (sel_b2) ? b : 1'b0;
  assign out_assign = (b1 & (a & b2) | (b1 & a) & (b2 & a));
  wire x = b1 & (a & b2) | (b1 & a) & (b2 & a);
  assign out_always = x;
endmodule

