module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  logic [1:0] up_down, state_reg_next, state_reg;
  logic [1:0] counter;

  assign counter = state_reg_next;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state_reg <= 0;
    end else begin
      state_reg <= state_reg_next;
    end
  end;

  assign up_down = (train_taken) ? 0 : 1;

  always @(*) begin
    state_reg_next = 0;
    case (counter)
      0: state_reg_next = 2'b01;
      1: state_reg_next = 2'b10;
      2: state_reg_next = 2'b11;
      3: state_reg_next = 2'b00;
      default: state_reg_next = 0;
    endcase
  end

  assign state = state_reg;

endmodule

module TopModule (
  input clk,
  input slowena,
  input reset,
  output reg [3:0] q
);
  reg [3:0] state, r, next_state;
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 4'b0000;
    end else begin
      state <= next_state;
    end
  end
  always @(*) begin
    case (state)
      4'b0000: next_state = 4'b0000;
      4'b0001: next_state = 4'b0010;
      4'b0010: next_state = 4'b0100;
      4'b0100: next_state = 4'b1000;
      4'b1000: next_state = 4'b0000;
      default: next_state = 4'b0000;
    endcase
  end
  always @(*) begin
    case (state)
      4'b0000: q = 4'b0000;
      4'b0001: q = 4'b0001;
      4'b0010: q = 4'b0010;
      4'b0100: q = 4'b0100;
      4'b1000: q = 4'b1000;
      default: q = 4'b0000;
    endcase
  end
endmodule

