module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);
// Module code based on the given circuit diagram.
reg [7:0] buffer;
assign Z = (A & B & C) | (A & ~B & C) | (~A & B & C) | (~A & ~B & ~C);

always @(posedge clk) begin
  if (enable) begin
