  wire z9 = x12 & x14; 

  wire z10 = z4 & z8; 
  wire z11 = z2 & z8; 
  wire z12 = z5 & z9; 
  wire z13 = z7 & z8; 
  wire z14 = z0 & z9; 
  wire z15 = z1 & z2; 
  wire z16 = z11 & z12; 

  assign z = z16 & z15; 
endmodule

module TopModule (
