module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);
  wire d_next = state[9] & done_counting; // direct path
  wire d_shift = state[8] & ack; // ack path
  wire d_count = state[7] & done_counting; // done_path
  wire d_shift2 = state[7] & done_counting; // d_count path

  assign Count_next = state[6] ? d_next : 1'b0;
  assign Wait_next = state[5] ? d_next : state[6] ? d_count : 1'b0;
  assign done = state[4] & d_shift & state[9] & d_next;
  assign counting = state[3] & d_shift2;
  assign shift_ena = state[2] & d_shift2 & done_counting;
  assign S_next = state[1] & d_shift2;
  assign S1_next = state[0] & d_shift2 & done_counting;
  assign B3_next = state[9] & done_counting;

  assign B3_next = state[9] & done_counting;
endmodule

module adder_32bit(A,B,S,C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire [32:1] c;
    wire [32:1] d;
    wire [32:1] e;

    for (int i = 1; i <= 31; i = i + 1) begin
        assign c[i] = d[i - 1];
        assign d[i] = A[i] ^ B[i] ^ c[i];
        assign e[i] = A[i] & B[i] & c[i];
    end

    assign c[32] = (A[32] ^ B[32] ^ c[31]) & (A[32] & B[32] & c[31]);
    assign d[32] = c[32];
    assign e[32] = 0;
    assign S[32] = c[32];
    assign S[31] = d[32];
    assign S[30] = d[31];
    assign S[29] = d[30];
    assign S[28] = d[29];
    assign S[27] = d[28];
    assign S[26] = d[27];
    assign S[25] = d[26];
    assign S[24] = d[25];
    assign S[23] = d[24];
    assign S[22] = d[23];
    assign S[21] = d[22];
    assign S[20] = d[21];
    assign S[19] = d[20];
    assign S[18] = d[19];
    assign S[17] = d[18];
    assign S[16] = d[17];
    assign S[15] = d[16];
    assign S[14] = d[15];
    assign S[13] = d[14];
    assign S[12] = d[13];
    assign S[11] = d[12];
    assign S[10] = d[11];
    assign S[9] = d[10];
    assign S[8] = d[9];
    assign S[7] = d[8];
    assign S[6] = d[7];
    assign S[5] = d[6];
    assign S[4] = d[5];
    assign S[3] = d[4];
    assign S[2] = d[3];
    assign S[1] = d[2];
endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [3:0] AB;  // Both numbers in the same bit width
    wire [4:0] adder_result;  // Result of internal addition
    // Check if A + B >= 10, which requires extra carry from the sixth bit
    wire [3:0] sum_result = adder_result [4:1];
    wire carry_signal = adder_result [5];

    // Calculate the actual sum of the resistances (A + B) using a full adder
    assign AB = A + B;
    assign adder_result = AB + Cin;
    assign Sum = sum_result;
    assign Cout = carry_signal;
endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);
    wire A1, B1, A2, B2, A3, B3, A4, B4, A5, B5, A6, B6;
    wire A3_0, B3_0, A2_1, B2_1, A1_2, B1_2, A0_3, B0_3, c1, c2, c3, c4, c5, dn, wn, k, s, f;
    wire p, q, r, t, u, v, w, x, y, z, aa, bb, cc, dd, ee, ff, gg;

    assign A1 = A[2];
    assign B1 = B[2];
    assign A2 = A[1];
    assign B2 = B[1];
    assign A3 = A[0];
    assign B3 = B[0];

    assign A3_0 = A3 & B3;
    assign B3_0 = A3 & B3;
    assign A2_1 = A2 & B2;
    assign B2_1 = A2 & B2;
    assign A1_2 = A1 & B1;
    assign B1_2 = A1 & B1;
    assign A0_3 = A3 | A2 | A1;
    assign B0_3 = B3 | B2 | B1;

    assign c1 = A1_2 | A4;
    assign c2 = A2_1 | c1;
    assign c3 = A3_0 | c2;
    assign dn = c3 & A3_0 & A2; // something implied also via equations for below un-Realized truth tables
    assign wn = c3 & A3_0 & B2;

    assign k = c3 & A3_0;
    assign s = dn & A3_0;

    assign f = c3 & A3_0 & A2 & B1;

    assign t = k | s | f;
    assign u = c2 & c1 & A3_0;
    assign v = c2 & c1 & A2_1 & A3_0;
    assign w = c2 & c1 & A2_1 & A3_0 & A1_2;
    assign x = c2 & c1 & A2_1 & A3_0 & A1_2 & s;

    assign aa = A3 & B3 & c2;
    assign bb = A2 & B2 & c2 & A3 & B3 & c1 & c2;
    assign cc = A2 & B2 & c2; // also valid form of this expression
    assign dd = A1 & B1 & c2; // as much as question allows
    assign ee = (c2 & c1 & A2 & B2) | (c2 & c1 & A2 & B2 & A1 & B1) | (c2 & c1 & A2 & B2 & A1 & B1 & A3 & B3);
    assign ff = c2 & c1 & A2_1;
    assign gg = (A3 & B3 & c3) | (A2 & B2 & c3) | (A1 & B1 & c3) | (A0_3 & c3);
    assign A_greater = A3_0 & u & v & w & x & t; // i.e. c3 & A3 & B3 & c2 & c1 & A2 & B2 & A1_2 & s & t
    assign A_less = B3_0 & e & d & c & b & a & t; // similar but with inverted A and B within push downs
    assign A_equal = c3 & c2 & c1 & c0 & not (u | v | w | x | t) & not (e | d | c | b | a | t); 
endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);
    assign A_equal = (A == B);
    assign A_greater = (A > B);
    assign A_less = (A < B);
endmodule

module edge_detect(
    input clk,
    input rst_n,
    input a,

    output reg rise,
    output reg down
);
    reg [1:0] s0, s1, s2;
    reg [1:0] d0, d1, d2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s0 <= 0;
            s1 <= 0;
            s2 <= 0;
        end else begin
            s0 <= d0;
            s1 <= d1;
            s2 <= d2;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            d0 <= 0;
            d1 <= 0;
            d2 <= 0;
        end else begin
            d0 <= (a & !s0) | (!a & s0);
            d1 <= (a & !s1) | (!a & s1);
            d2 <= (a & !s2) | (!a & s2);
        end
    end

    assign rise = s2 & !s0;
    assign down = s2 & !s1;
endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            clk_div <= 0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 0;
                clk_div <= 1;
            end else begin
                counter <= counter + 1;
                clk_div <= 0;
            end
        end
    end
endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);
// D flip-flops (assuming them to be the desired elements) for each bit.
always @(posedge clk or posedge rst) begin
    if (rst) begin
        for (int i = 0; i < 19; i = i + 1) begin
            $S_FF_PNON_Q[i] <= 1'b0;
        end
    end else if (fetch == 2'b00) begin
        for (int i = 0; i < 19; i = i + 1) begin
            $S_FF_PNON_Q[i] <= $S_FF_PNON_D[i];
        end
    end
end

// Theorem from digital design, need to apply the truth table of D' flip flop.
// In the cell, the next state of each flip flop is determined by D for each cell.
assign $S_FF_PNON_D[0] = 1'b0;  // For simplicity, hardwiring D for the purposes of the expression.
for (int i = 0; i < 19; i = i + 1) begin
    assign $S_FF_PNON_D[i] = $S_FF_PNON_Q[i - 1];
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        ins <= 3'b0;
        ad1 <= 5'b0;
        ad2 <= 8'b0;
    end else begin
        ins <= $S_FF_PNON_Q[17];
        ad1 <= $S_FF_PNON_Q[18];
        ad2 <= $S_FF_PNON_Q[19];
    end
end
endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;
  reg [3:0] Q, D;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      Q <= 0;
    end else begin
      D <= {Q[3], Q[2], Q[1] ^ Q[3]};
      Q <= D;
      out <= Q;
    end
  end
endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input d;  
    output  [7:0] q;

    reg [7:0] q_reg;
    reg [7:0] next_q_reg;    

    always @(posedge clk) begin
        if (clk) begin
            next_q_reg[0] <= q_reg[1];
            next_q_reg[1] <= q_reg[2];
            next_q_reg[2] <= q_reg[3];
            next_q_reg[3] <= q_reg[4];
            next_q_reg[4] <= q_reg[5];
            next_q_reg[5] <= q_reg[6];
            next_q_reg[6] <= q_reg[7];
            next_q_reg[7] <= d;
        end
    end

    always @(posedge clk) begin
        q_reg <= next_q_reg;
    end
endmodule

