module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [12:0] count;
reg [3:0] state;
wire [3:0] not_state;

// Initial state and state transition
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        count <= 0;
        state <= 0;
    end
    else begin
        case(state)
            0: begin
                count <= 0;
                if (IN) begin
                    state <= 1;
                end
                else state <= 0;
            end
            1: begin
                count <= count + 1;
                state <= 1;
            end
            2: begin
                count <= 0;
                if (IN) begin
                    state <= 3;
                end
                else begin
                    state <= 1;
                end
            end
            3: begin
                count <= count + 1;
                state <= 3;
            end
        endcase
    end
end

// Match output when state is 5
assign MATCH = (state == 5) ? 1 : 0;

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [3:0] count;

    reg [3:0] q;
    reg d_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q <= 4'b0;
            d_out <= 0;
        end else begin
            q <= {q[2:0], d[3]};
            if (count == 0) begin
                d_out <= q[0];
            end
            count <= count + 1;
            if (count == 4) begin
                count <= 0;
            end
        end
    end

    assign valid_out = (count == 4);
    assign dout = d_out;
endmodule

