module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

  reg [3:0] state, next_state; // State machine states for detecting sequence

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= 4'b0000;
    end
    else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      4'b0000: next_state = (data_in) ? 4'b0001 : 4'b0000;
      4'b0001: next_state = (data_in) ? 4'b0010 : 4'b0000;
      4'b0010: next_state = (data_in) ? 4'b0100 : 4'b0000;
      4'b0100: next_state = (data_in) ? 4'b1000 : 4'b0000;
      4'b1000: next_state = (data_in) ? 4'b0000 : 4'b0000;
      default: next_state = 4'b0000;
    endcase
  end

  assign sequence_detected = (state == 4'b1000);

endmodule
